public class ArrayGuard {
    public static void main(String[] args) {
        int[] values = {4, 7, 9};
        int index = 3;
        if (index >= 0 && index < values.length && values[index] > 0) {
            System.out.println(values[index]);
        } else {
            System.out.println("Index is outside the array");
        }
    }
}

